import { SqliteDurableObject, createDb } from "rwsdk/db";
import { env } from "cloudflare:workers";

export interface Database {
  auction_results: {
    item_id: string;
    winner_name: string;
    winning_amount: number;
    closed: number;
  };
}

export const migrations = {
  "001_create_auction_results": {
    async up(db: any) {
      await db.schema
        .createTable("auction_results")
        .addColumn("item_id", "text", (col: any) => col.primaryKey())
        .addColumn("winner_name", "text", (col: any) => col.notNull())
        .addColumn("winning_amount", "integer", (col: any) => col.notNull())
        .addColumn("closed", "integer", (col: any) => col.notNull().defaultTo(1))
        .execute();
    },
    async down(db: any) {
      await db.schema.dropTable("auction_results").execute();
    }
  }
};

export class DbServer extends SqliteDurableObject {
  constructor(ctx: DurableObjectState, env: any) {
    super(ctx, env, migrations);
  }
}

export const getDb = () => {
  if (!env.DB_SERVER) {
    throw new Error("DB_SERVER binding is missing");
  }
  return createDb<Database>(env.DB_SERVER);
};

export async function saveAuctionResult(itemId: string, winnerName: string, winningAmount: number) {
  const db = getDb();
  const existing = await db
    .selectFrom("auction_results")
    .selectAll()
    .where("item_id", "=", itemId)
    .executeTakeFirst();

  if (existing) {
    await db
      .updateTable("auction_results")
      .set({
        winner_name: winnerName || "No one",
        winning_amount: winningAmount,
        closed: 1,
      })
      .where("item_id", "=", itemId)
      .execute();
  } else {
    await db
      .insertInto("auction_results")
      .values({
        item_id: itemId,
        winner_name: winnerName || "No one",
        winning_amount: winningAmount,
        closed: 1,
      })
      .execute();
  }
}

export async function getAuctionResult(itemId: string) {
  try {
    const db = getDb();
    const result = await db
      .selectFrom("auction_results")
      .selectAll()
      .where("item_id", "=", itemId)
      .executeTakeFirst();
    return result;
  } catch (e) {
    console.error("Error reading from DB:", e);
    return undefined;
  }
}

import { SyncedStateServer } from "rwsdk/use-synced-state/worker";
import { saveAuctionResult, getAuctionResult } from "./db.js";

export class AuctionRoomServer extends SyncedStateServer {
  env: any;
  itemId?: string;

  constructor(ctx: DurableObjectState, env: any) {
    super(ctx, env);
    this.env = env;
  }

  async initializeAuction(itemId: string) {
    this.itemId = itemId;
    await this.ctx.storage.put("itemId", itemId);

    // Check if already closed in DB
    const dbResult = await getAuctionResult(itemId);
    if (dbResult) {
      this.setState(true, "closed");
      this.setState(dbResult.winner_name, "highestBidder");
      this.setState(dbResult.winning_amount, "winning_amount");
      // Set highestBid to winning_amount too for backward compatibility
      this.setState(dbResult.winning_amount, "highestBid");
      this.setState(0, "timeLeft");
      return;
    }

    // Check if countdown already initialized in memory
    let timeLeft = this.getState("timeLeft");
    if (timeLeft === undefined) {
      const duration = itemId === "lot-42" ? 25 : 60;
      const startingPrice = itemId === "lot-42" ? 50 : 10;
      const itemName = itemId === "lot-42" ? "Sunburst Electric Guitar" : `Item ${itemId}`;

      this.setState(itemName, "itemName");
      this.setState(startingPrice, "highestBid");
      this.setState("", "highestBidder");
      this.setState(duration, "timeLeft");
      this.setState(false, "closed");

      // Start the countdown alarm!
      await this.ctx.storage.setAlarm(Date.now() + 1000);
    }
  }

  async placeBid(bidderName: string, bidAmount: number) {
    if (!this.itemId) {
      this.itemId = await this.ctx.storage.get<string>("itemId");
    }
    if (!this.itemId) {
      throw new Error("Auction room not initialized");
    }

    // Check if already closed in DB
    const dbResult = await getAuctionResult(this.itemId);
    if (dbResult || this.getState("closed")) {
      throw new Error("Auction is closed");
    }

    const highestBid = this.getState("highestBid") as number;
    const highestBidder = this.getState("highestBidder") as string;

    const startingPrice = this.itemId === "lot-42" ? 50 : 10;
    const hasAcceptedBid = highestBidder !== "";

    if (bidAmount < startingPrice) {
      throw new Error(`Bid must be at least the starting price of $${startingPrice}`);
    }

    if (hasAcceptedBid && bidAmount <= highestBid) {
      throw new Error(`Bid must be strictly greater than the current highest bid of $${highestBid}`);
    }

    // Validation passed! Update state
    this.setState(bidAmount, "highestBid");
    this.setState(bidderName, "highestBidder");

    return { success: true };
  }

  async fetch(request: Request) {
    const url = new URL(request.url);
    const parts = url.pathname.split("/").filter(Boolean);
    const itemId = parts[parts.length - 1]; // E.g., /__synced-state/lot-42 -> "lot-42"
    if (itemId && itemId !== "__synced-state") {
      await this.initializeAuction(itemId);
    }
    return super.fetch(request);
  }

  async alarm() {
    if (!this.itemId) {
      this.itemId = await this.ctx.storage.get<string>("itemId");
    }
    if (!this.itemId) return;

    let timeLeft = this.getState("timeLeft") as number;
    if (timeLeft === undefined) return;

    if (timeLeft > 0) {
      timeLeft--;
      this.setState(timeLeft, "timeLeft");

      if (timeLeft === 0) {
        this.setState(true, "closed");
        const highestBid = this.getState("highestBid") as number;
        const highestBidder = this.getState("highestBidder") as string;

        // Persist to DB
        await saveAuctionResult(this.itemId, highestBidder, highestBid);
      } else {
        await this.ctx.storage.setAlarm(Date.now() + 1000);
      }
    }
  }
}

"use server";

import { env } from "cloudflare:workers";

export async function placeBidAction(itemId: string, bidderName: string, bidAmount: number) {
  try {
    const namespace = env.SYNCED_STATE_SERVER;
    if (!namespace) {
      return { success: false, error: "SYNCED_STATE_SERVER binding is missing" };
    }
    const id = namespace.idFromName(itemId);
    const stub = namespace.get(id);

    // Call the RPC method on the Durable Object!
    await stub.placeBid(bidderName, bidAmount);
    return { success: true };
  } catch (e: any) {
    return { success: false, error: e.message || String(e) };
  }
}

"use client";

import { useState, useTransition } from "react";
import { useSyncedState } from "rwsdk/use-synced-state/client";
import { placeBidAction } from "../actions.js";

interface AuctionRoomClientProps {
  itemId: string;
  clientName: string;
  initialClosed: boolean;
  initialWinner: string;
  initialAmount: number;
}

export const AuctionRoomClient = ({
  itemId,
  clientName,
  initialClosed,
  initialWinner,
  initialAmount,
}: AuctionRoomClientProps) => {
  const [itemName] = useSyncedState(
    itemId === "lot-42" ? "Sunburst Electric Guitar" : `Item ${itemId}`,
    "itemName",
    itemId
  );

  const [highestBid] = useSyncedState(
    initialAmount,
    "highestBid",
    itemId
  );

  const [highestBidder] = useSyncedState(
    initialWinner,
    "highestBidder",
    itemId
  );

  const [timeLeft] = useSyncedState(
    itemId === "lot-42" ? 25 : 60,
    "timeLeft",
    itemId
  );

  const [closed] = useSyncedState(
    initialClosed,
    "closed",
    itemId
  );

  const [bidValue, setBidValue] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [isPending, startTransition] = useTransition();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    const amount = parseInt(bidValue, 10);
    if (isNaN(amount)) {
      setError("Please enter a valid whole number.");
      return;
    }

    startTransition(async () => {
      try {
        const res = await placeBidAction(itemId, clientName, amount);
        if (res.success) {
          setBidValue("");
        } else {
          setError(res.error || "Bid was rejected.");
        }
      } catch (err: any) {
        setError(err.message || "An unexpected error occurred.");
      }
    });
  };

  return (
    <div style={{ padding: "30px", fontFamily: "sans-serif", maxWidth: "600px", margin: "40px auto", border: "1px solid #eaeaea", borderRadius: "8px", boxShadow: "0 4px 12px rgba(0,0,0,0.05)" }}>
      <h1 data-testid="item-name" style={{ fontSize: "2rem", marginBottom: "20px", color: "#333" }}>{itemName}</h1>

      <div style={{ padding: "10px 15px", backgroundColor: "#f8f9fa", borderRadius: "6px", marginBottom: "20px" }}>
        <strong>Your Identity: </strong>
        <span data-testid="my-name" style={{ fontWeight: "bold", color: "#007bff" }}>{clientName}</span>
      </div>

      <div style={{ display: "flex", gap: "20px", marginBottom: "25px" }}>
        <div style={{ flex: 1, padding: "15px", border: "1px solid #eee", borderRadius: "6px", textAlign: "center" }}>
          <div style={{ color: "#666", fontSize: "0.9rem", marginBottom: "5px" }}>Current Highest Bid</div>
          <span data-testid="current-bid" style={{ fontSize: "1.5rem", fontWeight: "bold", color: "#28a745" }}>${highestBid}</span>
        </div>
        <div style={{ flex: 1, padding: "15px", border: "1px solid #eee", borderRadius: "6px", textAlign: "center" }}>
          <div style={{ color: "#666", fontSize: "0.9rem", marginBottom: "5px" }}>Highest Bidder</div>
          <span data-testid="high-bidder" style={{ fontSize: "1.5rem", fontWeight: "bold" }}>{highestBidder || "None"}</span>
        </div>
      </div>

      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "25px", padding: "10px 15px", backgroundColor: "#fff3cd", border: "1px solid #ffeeba", borderRadius: "6px" }}>
        <strong>Time Remaining:</strong>
        <span data-testid="time-left" style={{ fontSize: "1.2rem", fontWeight: "bold", color: "#856404" }}>{timeLeft}s</span>
      </div>

      {closed ? (
        <div
          data-testid="winner"
          style={{
            padding: "20px",
            backgroundColor: "#d4edda",
            color: "#155724",
            border: "1px solid #c3e6cb",
            borderRadius: "6px",
            marginBottom: "25px",
            fontWeight: "bold",
            textAlign: "center",
            fontSize: "1.1rem"
          }}
        >
          Winner: {highestBidder || "No one"} with ${highestBid}
        </div>
      ) : null}

      <form onSubmit={handleSubmit} style={{ display: "flex", gap: "12px", marginTop: "20px" }}>
        <input
          type="number"
          data-testid="bid-input"
          value={bidValue}
          onChange={(e) => setBidValue(e.target.value)}
          disabled={closed}
          placeholder="Enter bid amount"
          style={{
            flex: 1,
            padding: "12px",
            borderRadius: "6px",
            border: "1px solid #ccc",
            fontSize: "1rem"
          }}
        />
        <button
          type="submit"
          data-testid="place-bid"
          disabled={closed}
          style={{
            padding: "12px 24px",
            borderRadius: "6px",
            border: "none",
            backgroundColor: closed ? "#6c757d" : "#007bff",
            color: "#fff",
            fontSize: "1rem",
            fontWeight: "bold",
            cursor: closed ? "not-allowed" : "pointer",
            transition: "background-color 0.2s"
          }}
        >
          Place Bid
        </button>
      </form>

      {error ? (
        <div
          data-testid="bid-error"
          style={{
            color: "#721c24",
            backgroundColor: "#f8d7da",
            border: "1px solid #f5c6cb",
            padding: "10px 15px",
            borderRadius: "6px",
            marginTop: "15px",
            fontWeight: "bold"
          }}
        >
          {error}
        </div>
      ) : null}
    </div>
  );
};

import { getRequestInfo } from "rwsdk/worker";
import { AuctionRoomClient } from "./auctionClient.js";
import { env } from "cloudflare:workers";
import { getAuctionResult } from "../db.js";

export const AuctionRoomPage = async () => {
  const requestInfo = getRequestInfo();
  const itemId = requestInfo.params.itemId;

  // Get the name query parameter, default to "Anonymous"
  const nameParam = requestInfo.query?.name;
  const clientName = Array.isArray(nameParam) ? nameParam[0] : nameParam || "Anonymous";

  // Trigger server-side auction initialization/check
  const namespace = env.SYNCED_STATE_SERVER;
  if (namespace) {
    const id = namespace.idFromName(itemId);
    const stub = namespace.get(id);
    // Call the RPC initialization method
    await stub.initializeAuction(itemId);
  }

  // Also query the DB directly to get the initial closed state if any
  const dbResult = await getAuctionResult(itemId);
  const isClosed = !!dbResult;
  const initialWinner = dbResult ? dbResult.winner_name : "";
  const initialAmount = dbResult ? dbResult.winning_amount : (itemId === "lot-42" ? 50 : 10);

  return (
    <AuctionRoomClient
      itemId={itemId}
      clientName={clientName}
      initialClosed={isClosed}
      initialWinner={initialWinner}
      initialAmount={initialAmount}
    />
  );
};

import { render, route } from "rwsdk/router";
import { defineApp } from "rwsdk/worker";
import { syncedStateRoutes } from "rwsdk/use-synced-state/worker";

import { Document } from "@/app/document";
import { setCommonHeaders } from "@/app/headers";
import { Home } from "@/app/pages/home";
import { AuctionRoomPage } from "@/app/pages/auction";

// Export Durable Objects
export { AuctionRoomServer as SyncedStateServer } from "@/app/auctionServer";
export { DbServer } from "@/app/db";

export type AppContext = {};

export default defineApp([
  setCommonHeaders(),
  ({ ctx }) => {
    // setup ctx here
    ctx;
  },
  ...syncedStateRoutes((env) => env.SYNCED_STATE_SERVER),
  render(Document, [
    route("/", Home),
    route("/auction/:itemId", AuctionRoomPage),
  ]),
]);

